    'partners.heroText': { fr: 'Nous collaborons avec des entreprises, des organismes et des chercheurs qui partagent notre volonté de développer des technologies utiles, responsables et accessibles.', en: 'We work with companies, organizations, and researchers who share our commitment to developing useful, responsible, and accessible technologies.' },
