const LocaleContext = createContext<{
    locale: Locale;
    setLocale: (locale: Locale) => void;
    toggleLocale: () => void;
    t: (key: string) => string;
    translateData: <T>(value: T, namespace?: string) => T;
}>({
    locale: 'fr',
    setLocale: () => undefined,
    toggleLocale: () => undefined,
    t: (key) => key,
    translateData: <T,>(value: T) => value,
});

function translateValue<T>(value: T, locale: Locale, path = ''): T {
    if (locale === 'fr') return value;
    if (typeof value === 'string') return ((dataMessages[path] ?? messages[path])?.[locale] ?? legacyDataTranslations[value] ?? value) as T;
    if (Array.isArray(value)) {
        return value.map((item, index) => {
            const itemId = item && typeof item === 'object' && !Array.isArray(item) ? ('slug' in item ? item.slug : item.id) : undefined;
            return translateValue(item, locale, itemId ? `${path}.${itemId}` : `${path}.${index}`);
        }) as T;
    }
    if (value && typeof value === 'object') {
        return Object.fromEntries(
            Object.entries(value).map(([key, item]) => [key, translateValue(item, locale, path ? `${path}.${key}` : key)]),
        ) as T;
    }
    return value;
}

export function LocaleProvider({ children }: { children: ReactNode }) {
    const [locale, setLocaleState] = useState<Locale>(() => {
        const stored = window.localStorage.getItem('heka-locale');
        return stored === 'en' ? 'en' : 'fr';
    });

    const setLocale = (nextLocale: Locale) => {
        setLocaleState(nextLocale);
        window.localStorage.setItem('heka-locale', nextLocale);
        document.documentElement.lang = nextLocale;
    };

    const value = useMemo(
        () => ({
            locale,
            setLocale,
            toggleLocale: () => setLocale(locale === 'fr' ? 'en' : 'fr'),
            t: (key: string) => messages[key]?.[locale] ?? key,
            translateData: <T,>(data: T, namespace = '') => translateValue(data, locale, namespace),
        }),
        [locale],
    );

    return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useLocale() {
    return useContext(LocaleContext);
}

export function navigationKey(pageId: string) {
    const keys: Record<string, string> = {
        accueil: 'nav.home',
        apropos: 'nav.about',
        projets: 'nav.projects',
        realisations: 'nav.achievements',
        equipe: 'nav.team',
        partenaires: 'nav.partners',
        contact: 'nav.contact',
    };

    return keys[pageId] ?? 'nav.projects';
}
